def pdiff(Ra, Rb, keys, f):
    d_ = np.array([f(Rb[k_]) - f(Ra[k_]) for k_ in keys], float); return d_.mean(), d_.std(ddof=1)/np.sqrt(len(d_)), np.mean([f(Ra[k_]) for k_ in keys]), np.mean([f(Rb[k_]) for k_ in keys])
fa = lambda r_: float(r_['all']); fi = lambda r_: float(np.mean(r_['oks'])) if len(r_['oks']) else np.nan; ft = lambda r_: float(r_['has_think'])
for nm_, f_ in [('prompt-level', fa), ('instr-mean per prompt', fi), ('has </think>', ft)]:
    m_, se_, a_, b_ = pdiff(R5s, R5e, keys5, f_); print('%-22s start %.3f F1 %.3f diff %+.3f (SE %.3f)' % (nm_, a_, b_, m_, se_))
rows_ = []
for k_ in keys5:
    for kd_, o1, o2 in zip(R5s[k_]['kinds'], R5s[k_]['oks'], R5e[k_]['oks']): rows_.append(dict(kind=kd_, s=bool(o1), e=bool(o2)))
KK = pd.DataFrame(rows_); tb_ = KK.groupby('kind').agg(n=('s','size'), start=('s','mean'), F1=('e','mean')); tb_['diff'] = tb_.F1 - tb_.start
print(tb_.sort_values('n', ascending=False).round(2).to_string())
print('instruction-level: start %.3f F1 %.3f' % (KK.s.mean(), KK.e.mean()))
M5s = grade_math([g_ for g_ in G5s if g_['id'].startswith('prompt/') and int(g_['id'].split('/')[1]) >= 200], MATH_S, 200)
M5e = grade_math([g_ for g_ in G5e if g_['id'].startswith('prompt/') and int(g_['id'].split('/')[1]) >= 200], MATH_S, 200)
for nm_, M_ in [('start', M5s), ('F1', M5e)]:
    v_ = list(M_.values()); print(nm_, 'math correct %.3f boxed %.3f has_think %.3f median after_box %s' % (np.mean([x_['ok'] for x_ in v_]), np.mean([x_['has_box'] for x_ in v_]), np.mean([x_['has_think'] for x_ in v_]), np.median([x_['after_box'] for x_ in v_ if x_['has_box']])))
